function batteryPage(i,m){"use strict";var u=[{v:0,rgb:[195,0,0]},{v:.15,rgb:[240,170,0]},{v:.25,rgb:[30,128,0]},{v:1,rgb:[30,128,0]}],n=document.getElementById(i.textElement),v=document.getElementById(i.widgetElement);g().then(e=>{var r="";if(e.errCode)switch(e.errCode){case 1:r="Your browser doesn't provide the Battery Status API.";break;case 2:r="Sorry, an error occurred on this page.";break}else e.level&&(r=`<div>Level <b>${(e.level*100).toFixed(0)}%</b></div><div><b>${e.charging?"Charging":"Not charging"}</b></div><div>Charging Time: <b>${t(e.chargingTime)}</b></div><div>Estimated Time to Discharge: <b>${t(e.dischargingTime)}</b></div>`);n.innerHTML=r});async function g(){const e={level:null,charging:"n/a",chargingTime:"n/a",dischargingTime:"n/a"};if(!navigator.getBattery||typeof navigator.getBattery!="function")return e.errCode=1,e;try{const r=await navigator.getBattery();return{level:Number.isFinite(r.level)?r.level:null,charging:r.charging,chargingTime:Number.isFinite(r.chargingTime)?r.chargingTime:"n/a",dischargingTime:Number.isFinite(r.dischargingTime)?r.dischargingTime:"n/a"}}catch{return e.errCode=2,e}}function t(e){if(typeof e!="number"||!Number.isFinite(e)||e<0)return"n/a";e=Math.floor(e);const r=Math.floor(e/86400),a=Math.floor(e%86400/3600),s=Math.floor(e%3600/60),c=e%60,h=r===1?"day":"days";return e<60?`${e} seconds`:`${r} ${h} ${String(a).padStart(2,"0")}:${String(s).padStart(2,"0")}:${String(c).padStart(2,"0")}`}}
